SELECT q.difficulty,COUNT(*) question_count FROM biz_programming_question_config c INNER JOIN biz_question q ON q.question_id=c.question_id
WHERE c.external_id IN (CONVERT(0x5059494F2D303031 USING utf8mb4),CONVERT(0x5059494F2D303032 USING utf8mb4),CONVERT(0x5059494F2D303033 USING utf8mb4),CONVERT(0x5059494F2D303034 USING utf8mb4),CONVERT(0x5059494F2D303035 USING utf8mb4)) GROUP BY q.difficulty ORDER BY q.difficulty;
SELECT COUNT(*) question_count,SUM(case_count) test_case_count FROM (SELECT c.question_id,COUNT(tc.test_case_id) case_count FROM biz_programming_question_config c INNER JOIN biz_programming_test_case tc ON tc.question_id=c.question_id
WHERE c.external_id IN (CONVERT(0x5059494F2D303031 USING utf8mb4),CONVERT(0x5059494F2D303032 USING utf8mb4),CONVERT(0x5059494F2D303033 USING utf8mb4),CONVERT(0x5059494F2D303034 USING utf8mb4),CONVERT(0x5059494F2D303035 USING utf8mb4)) GROUP BY c.question_id) x;
